import React, { useState } from 'react';
import { Text, View, Button, TouchableOpacity } from 'react-native';

import { ParamListBase, useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';

import { SvgProps } from 'react-native-svg'

type YourNavigatorProps = NativeStackNavigationProp<ParamListBase, keyof ParamListBase>

import { useContexState } from '../../hooks/context';
import { styles } from './styles'

export default function Checkout() {
    const navigation = useNavigation<YourNavigatorProps>();

    const {
        shoppingCartItem,
        shoppingCartActive,
        loginValue,
        selectedNumber,
        listData
    } = useContexState();

    const {
        setShoppingCartItem,
        setShoppingCartActive,
        setRegisterMenuActive,
    } = useContexState();

    const conta = shoppingCartItem.length * 19.90;
    const price = (conta).toLocaleString("pt-BR", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    });

    return (
        <View style={styles.container}>
            <TouchableOpacity style={{ backgroundColor: '#555', width: 0, height: 0, top: 0, position: 'absolute' }} onPress={() => navigation.navigate('Home')} />



            <View style={{
                backgroundColor: '#fff',
                height: '90%',
                width: '90%',
                borderRadius: 10,
                alignItems: 'center',
                justifyContent: 'space-between',
            }}>
                <View style={{ alignItems: 'flex-end', width: '90%', padding: 15 }} >
                    <Text style={{ fontSize: 18 }}>{shoppingCartItem.length} NÚMEROS POR APENAS</Text>
                    <Text style={{ fontSize: 40 }}>R$ {price}</Text>
                </View>


                <View style={{
                    alignItems: 'center',
                    paddingVertical: 20,
                    paddingHorizontal: 10
                }}>
                    <Text style={{
                        fontSize: 25,
                        color: '#000',
                        top: 15,
                        width: '95%',
                        paddingVertical: 7,
                        padding: 10,
                        textAlign: 'center'
                    }}>
                        <Text style={{ fontSize: 32 }}>Pagar com Pix</Text>
                        {'\n'}é facil é rápido!</Text>


                    <Text style={{
                        fontSize: 17,
                        color: '#000',
                        width: '95%',
                        padding: 7
                    }}>• Abra o seu aplicativo Pix do seu
                        Banco ou empresa de Pagamento.</Text>

                    <Text style={{
                        fontSize: 17,
                        color: '#000',
                        width: '95%',
                        padding: 7
                    }}>• Clique em Pagar Pix no seu
                        Aplicativo e aponte a câmera para o QR Code Pix.</Text>

                    <Text style={{
                        fontSize: 17,
                        color: '#000',
                        width: '95%',
                        padding: 7
                    }}>• Pronto, agora é só finalizar
                        o pagamento e aguardar a Aprovação.</Text>

                    <Text style={{
                        fontSize: 17,
                        color: '#000',
                        width: '95%',
                        padding: 7
                    }}>• Se preferir, Copie e Cole o
                        Código Pix no seu Aplicativo ou Site Pix.</Text>

                </View>


            </View>
        </View >
    )
}
